tool_input.content:
- id: R1
  status: done
  title: "CSV Analytics Tool"
  quote: "Build a CSV Analytics Tool. Read CSV files, compute per-column stats (count, min, max, mean, median, stdev), filter rows, select columns, export JSON report. Single file csv_analytics.py, stdlib only."
  steps:
    - {do: "Spec written and linted", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec lint forgemyspec-bundle/csv-analytics/spec.yaml --formal"}
    - {do: "User approved the spec bundle (ran approve in own terminal)", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec lock --check forgemyspec-bundle/csv-analytics"}
    - {do: "csv_analytics.py implemented, boundary tests pass", check: "cmd: python3 -m unittest discover -s tests"}
    - {do: "Gate reports RESULT: PASS", check: "cmd: PYTHONPATH=.forgemyspec/harness python3 -m forgemyspec gate forgemyspec-bundle/csv-analytics | grep -q 'RESULT: PASS'"}
  evidence: "gate: lint, coverage, spec lock, 8 boundary tests all PASS"
